SELECT P.POSUUID, CASE WHEN INSTR(T.PROPERTYCODE,'AMT1')>0 THEN '1.期末理财资金投向情况' WHEN INSTR(T.PROPERTYCODE,'AMT2')>0 THEN '2.期末理财负债情况' WHEN INSTR(T.PROPERTYCODE,'AMT3')>0 THEN '3.附注' end reportType1, L.ITEM_VALUE reportType2, T.PROPERNAME reportType3, T.PROPERNAME reportType4, P.PROD_ID prodId, B.PROD_NAME prodName, B.IS_FHXGCP , P.ASSET_CODE, NVL(I.ASSET_NAME,B.SUBJECT_NAME) ASSET_NAME, P.OLD_ASSET_CODE, IA.ASSET_NAME OLD_ASSET_NAME, NVL(I.VDATE,I.PLAN_SDATE) VDATE, NVL(I.MDATE,I.PLAN_EDATE) MDATE, I.exercise_date, NVL2(I.chb_issuer_id,I.chb_financier_id,I.chb_manager_id) SUBJECT_NAME, I.rival_party, I.asset_yield RATE, P.CCY, AP.TDY_COST_AMT COST_AMT, AP.TDY_FLOAT_INGPL FLOAT_INGPL, AP.TDY_INTINCEXP INTINCEXP, P.ASSETVALUE_A, P.ASSETVALUE_B, P.PRIVATEPRD_FLAG, P.PRIVATEFUND_FLAG, P.MAIN_GRADE, P.CREDIT_GRADE, P.RATING, P.BONDTOSTOCK_FLAG, P.IS_GOVERN_FUND1, I.ORG_ASSET_TYPE1, I.ORG_ASSET_TYPE2, I.ORG_ASSET_TYPE3 FROM CHB_MONTH_REPORT_TEMPLATE T LEFT JOIN CHB_MONTH_ASSET_POSITIONDETAIL P ON T.PROPERTYCODE = P.DETAILNO LEFT JOIN CHB_ASSET_INFO I ON P.ASSET_CODE = I.ASSET_CODE LEFT JOIN CHB_ASSET_INFO IA ON IA.ASSET_CODE = P.OLD_ASSET_CODE LEFT JOIN BOK_SUBJECT B ON B.BOOKSET_ID = '00000000000000000002' AND B.SUBJECT_NO = P.ASSET_CODE LEFT JOIN CHB_PRD_BASEINFO B ON P.PROD_ID = B.PROD_ID LEFT JOIN SYS_DATADICT_LIST L ON L.ITEM_CODE = REPLACE(SUBSTR(T.PROPERTYCODE,0,7),'_','') AND L.DICT_CODE = 'SVR_MONTH_REPORT_DETAIL' LEFT JOIN CHB_ASSETS_BASIS_DATA AP ON AP.PROD_ID = P.PROD_ID AND AP.ASSET_ID = P.ASSET_CODE AND AP.VALUE_DATE = DECODE(P.TERM,NULL,TO_DATE('19000101','yyyyMMdd'),ADD_MONTHS(TO_DATE(P.TERM||'01','yyyyMMdd'),1)-1)
